let lang=localStorage.getItem('adg-lang')||'pt'
let theme=localStorage.getItem('adg-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')
let current=0
let mode='example'
let activeModal=null
let modalTrigger=null
let selectedFile=null
const $=(s,r=document)=>r.querySelector(s)
const $$=(s,r=document)=>[...r.querySelectorAll(s)]

function applyLang(){
  document.documentElement.lang=lang==='pt'?'pt-BR':'en'
  $('#langBtn').textContent=lang==='pt'?'PT-BR':'EN'
  $$('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(copy[lang][key])el.textContent=copy[lang][key]})
  $('#taskText').placeholder=lang==='pt'?'Ex.: compare as faixas salariais por departamento sem expor identificadores pessoais.':'Example: compare salary ranges by department without exposing personal identifiers.'
  $('#contentText').placeholder=lang==='pt'?'Cole aqui o conteúdo que deseja testar...':'Paste the content you want to test here...'
  $('#removeFile').setAttribute('aria-label',lang==='pt'?'Remover arquivo':'Remove file')
  $$('.modal [data-close]').forEach(btn=>btn.setAttribute('aria-label',lang==='pt'?'Fechar':'Close'))
}

function setTheme(next){
  theme=next
  document.documentElement.dataset.theme=theme
  $('#themeBtn').textContent=theme==='dark'?'☀':'☾'
  $('#themeBtn').setAttribute('aria-label',lang==='pt'?(theme==='dark'?'Usar tema claro':'Usar tema escuro'):(theme==='dark'?'Use light theme':'Use dark theme'))
  localStorage.setItem('adg-theme',theme)
}

function go(n){
  current=n
  $$('.screen').forEach(s=>s.classList.toggle('active',Number(s.dataset.screen)===n))
  $('#stepper').classList.toggle('is-hidden',n===0)
  const steps=$$('.step'),connectors=$$('.connector')
  steps.forEach((step,i)=>{
    const stepNumber=i+1
    step.classList.toggle('active',stepNumber===n)
    step.classList.toggle('done',stepNumber<n)
    step.querySelector('span').textContent=stepNumber<n?'✓':String(stepNumber)
  })
  connectors.forEach((c,i)=>c.classList.toggle('done',i+1<n))
  window.scrollTo({top:0,behavior:'smooth'})
  history.replaceState(null,'',`${location.pathname}?step=${n}&theme=${theme}&lang=${lang}&mode=${mode}`)
}

function choose(next,{focus=false}={}){
  mode=next
  $$('.segment').forEach(tab=>{
    const selected=tab.dataset.mode===mode
    tab.classList.toggle('selected',selected)
    tab.setAttribute('aria-selected',String(selected))
    tab.tabIndex=selected?0:-1
    if(selected&&focus)tab.focus()
  })
  $$('.input-panel').forEach(panel=>panel.hidden=panel.id!==`panel-${mode}`)
  if(mode==='example'){
    $('#taskText').value=lang==='pt'?'Compare as faixas salariais por departamento sem expor identificadores pessoais.':'Compare salary ranges by department without exposing personal identifiers.'
  }
  history.replaceState(null,'',`${location.pathname}?step=${current}&theme=${theme}&lang=${lang}&mode=${mode}`)
}

function start(next){
  choose(next)
  go(1)
}

function showFile(name,meta){
  $('#fileName').textContent=name
  $('#fileMeta').textContent=meta
  $('#fileCard').hidden=false
}

function setFile(file){
  if(!file)return
  selectedFile=file
  const kb=Math.max(1,Math.round(file.size/1024))
  showFile(file.name,`${file.type||(lang==='pt'?'arquivo':'file')} · ${kb} KB · ${lang==='pt'?'pronto para análise':'ready to analyze'}`)
}

function focusable(modal){
  return $$('button,[href],input,textarea,select,[tabindex]:not([tabindex="-1"])',modal).filter(el=>!el.disabled&&!el.hidden)
}

function openModal(id,trigger){
  const modal=document.getElementById(id)
  activeModal=modal
  modalTrigger=trigger||document.activeElement
  modal.classList.add('show')
  modal.setAttribute('aria-hidden','false')
  document.body.style.overflow='hidden'
  requestAnimationFrame(()=>{const items=focusable(modal);(items[0]||$('.modal-card',modal)).focus()})
}

function closeModal(modal){
  if(!modal)return
  modal.classList.remove('show')
  modal.setAttribute('aria-hidden','true')
  document.body.style.overflow=''
  activeModal=null
  if(modalTrigger&&typeof modalTrigger.focus==='function')modalTrigger.focus()
}

function handleModalKeydown(e){
  if(!activeModal)return
  if(e.key==='Escape'){e.preventDefault();closeModal(activeModal);return}
  if(e.key!=='Tab')return
  const items=focusable(activeModal)
  if(!items.length){e.preventDefault();return}
  const first=items[0],last=items[items.length-1]
  if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
  else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
}

$('#langBtn').addEventListener('click',()=>{
  lang=lang==='pt'?'en':'pt'
  localStorage.setItem('adg-lang',lang)
  applyLang();setTheme(theme)
})
$('#themeBtn').addEventListener('click',()=>setTheme(theme==='dark'?'light':'dark'))
$$('[data-go]').forEach(b=>b.addEventListener('click',()=>go(Number(b.dataset.go))))
$$('[data-start-mode]').forEach(b=>b.addEventListener('click',()=>start(b.dataset.startMode)))
$$('.segment').forEach(tab=>{
  tab.addEventListener('click',()=>choose(tab.dataset.mode))
  tab.addEventListener('keydown',e=>{
    if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return
    e.preventDefault()
    const tabs=$$('.segment'),index=tabs.indexOf(tab)
    let next=index
    if(e.key==='ArrowLeft')next=(index-1+tabs.length)%tabs.length
    if(e.key==='ArrowRight')next=(index+1)%tabs.length
    if(e.key==='Home')next=0
    if(e.key==='End')next=tabs.length-1
    choose(tabs[next].dataset.mode,{focus:true})
  })
})
$('#fileInput').addEventListener('change',e=>{setFile(e.target.files[0]);$('#inputValidation').textContent=''})
$('#removeFile').addEventListener('click',()=>{selectedFile=null;$('#fileCard').hidden=true;$('#fileInput').value=''})
const drop=$('#dropzone')
;['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.style.borderColor='var(--brand)'}))
;['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.style.borderColor=''}))
drop.addEventListener('drop',e=>{setFile(e.dataTransfer.files[0]);$('#inputValidation').textContent=''})
$('#analyzeBtn').addEventListener('click',()=>{
  const message=$('#inputValidation')
  message.textContent=''
  if(mode==='upload'&&!selectedFile){message.textContent=copy[lang].validationFile;$('#fileInput').focus();return}
  if(mode==='paste'&&!$('#contentText').value.trim()){message.textContent=copy[lang].validationText;$('#contentText').focus();return}
  if(!$('#taskText').value.trim()){message.textContent=copy[lang].validationTask;$('#taskText').focus();return}
  go(2)
})
$('#contentText').addEventListener('input',()=>{$('#inputValidation').textContent=''})
$('#taskText').addEventListener('input',()=>{$('#inputValidation').textContent=''})
$$('[data-modal]').forEach(b=>b.addEventListener('click',()=>openModal(b.dataset.modal,b)))
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>closeModal(b.closest('.modal'))))
$$('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModal(m)}))
document.addEventListener('keydown',handleModalKeydown)

const q=new URLSearchParams(location.search)
if(q.get('lang'))lang=q.get('lang')==='en'?'en':'pt'
if(['light','dark'].includes(q.get('theme')))theme=q.get('theme')
if(['example','upload','paste'].includes(q.get('mode')))mode=q.get('mode')
const startStep=Math.min(3,Math.max(0,Number(q.get('step')||0)))
setTheme(theme)
applyLang()
choose(mode)
go(startStep)